@@ -0,0 +1,12 @@
+const fs = require("fs");
+const assert = require("assert");
+const r = (p) => fs.readFileSync(p, "utf8");
+const hook = r("src/app/api/webhooks/stripe/route.ts");
+assert(!/subscription\.current_period_end/.test(hook));
+assert(hook.includes("items.data[0]?.current_period_end"));
+assert(hook.includes("parent?.subscription_details"));
+assert(!/payment_method_types/.test(r("src/trpc/index.ts")));
+assert(r("src/lib/stripe.ts").includes("2026-09-30.endive"));
+const v = JSON.parse(r("node_modules/stripe/package.json")).version;
+assert(v.startsWith("23."), v);
+console.log("ok");
